import React, { memo, useEffect, useMemo, useState } from "react";
import { useAppContext } from "../context/AppContext";

const formatResourceLabel = (resource) =>
  resource.floor ? `${resource.name} - ${resource.floor}` : resource.name;

const safe = (value) =>
  typeof value === "object" ? JSON.stringify(value) : value;

const BookingForm = ({
  formData = {},
  onChange = () => {},
  onSubmit = () => {},
  onAvailabilityCheck = () => {},
  availabilityMsg,
  loading,
}) => {
  const {
    blocks,
    resources: globalResources,
    dataLoaded,
    prefetching,
    fetchInitialData,
  } = useAppContext();

  const safeFormData = {
    resourceScope: "block",
    blockId: "",
    resourceId: "",
    name: "",
    department: "",
    bookingDate: "",
    startTime: "",
    endTime: "",
    purpose: "",
    ...formData,
  };

  const [resources, setResources] = useState([]);
  const [resourceLoading, setResourceLoading] = useState(false);
  const today = new Date().toISOString().slice(0, 10);

  useEffect(() => {
    fetchInitialData();
  }, [fetchInitialData]);

  useEffect(() => {
    if (safeFormData.resourceScope === "block" && !safeFormData.blockId) {
      setResources([]);
      setResourceLoading(false);
      return;
    }

    const cacheKey =
      safeFormData.resourceScope === "extra"
        ? "extra"
        : safeFormData.blockId;

    setResourceLoading(true);

    const timeoutId = setTimeout(() => {
      setResources(globalResources?.[cacheKey] || []);
      setResourceLoading(false);
    }, 250);

    return () => clearTimeout(timeoutId);
  }, [safeFormData.blockId, safeFormData.resourceScope, globalResources]);

  const blockOptions = useMemo(() => blocks || [], [blocks]);

  const handleScopeChange = (value) => {
    onChange({ target: { name: "resourceScope", value } });
    onChange({ target: { name: "blockId", value: "" } });
    onChange({ target: { name: "resourceId", value: "" } });
  };

  const handleBlockChange = (event) => {
    onChange({ target: { name: "blockId", value: event.target.value } });
    onChange({ target: { name: "resourceId", value: "" } });
  };

  const scopeIsBlock = safeFormData.resourceScope === "block";

  return (
    <div className="panel-card booking-card-shell">
      <div className="panel-header">
        <div>
          <h3>Create Booking</h3>
          <p>Fill details and reserve your slot.</p>
        </div>
      </div>

      <div className="scope-toggle">
        <button
          type="button"
          className={`scope-chip ${scopeIsBlock ? "active" : ""}`}
          onClick={() => handleScopeChange("block")}
        >
          Block
        </button>
        <button
          type="button"
          className={`scope-chip ${!scopeIsBlock ? "active" : ""}`}
          onClick={() => handleScopeChange("extra")}
        >
          Extra Centers
        </button>
      </div>

      {prefetching || !dataLoaded ? <div className="skeleton-line" /> : null}

      <form className="grid-form" onSubmit={onSubmit}>

        {/* ✅ NAME */}
        <label>
          <span>Your Name</span>
          <input
            type="text"
            name="name"
            value={safeFormData.name}
            onChange={onChange}
            required
            readOnly={Boolean(safeFormData.name)}
          />
        </label>

        {/* ✅ DEPARTMENT */}
        <label>
          <span>Department</span>
          <input
            type="text"
            name="department"
            value={safeFormData.department}
            onChange={onChange}
            required
          />
        </label>

        {/* ✅ BLOCK */}
        {scopeIsBlock ? (
          <label>
            <span>Block</span>
            <select
              value={safeFormData.blockId}
              onChange={handleBlockChange}
              required
            >
              <option value="">Select block</option>
              {blockOptions.map((block) => (
                <option key={block.id} value={block.id}>
                  Block {block.name}
                </option>
              ))}
            </select>
          </label>
        ) : (
          <div className="selection-summary">
            <span>Extra Centers</span>
          </div>
        )}

        {/* ✅ RESOURCE */}
        <label>
          <span>Resource</span>
          <select
            name="resourceId"
            value={safeFormData.resourceId}
            onChange={onChange}
            required
            disabled={scopeIsBlock && !safeFormData.blockId}
          >
            <option value="">
              {scopeIsBlock && !safeFormData.blockId
                ? "Select block first"
                : resourceLoading
                ? "Loading resources..."
                : resources.length === 0
                ? "No resources found"
                : "Select resource"}
            </option>

            {resources.map((resource) => (
              <option key={resource.id} value={resource.id}>
                {formatResourceLabel(resource)}
              </option>
            ))}
          </select>
        </label>

        {/* ✅ DATE */}
        <label>
          <span>Date</span>
          <input
            type="date"
            name="bookingDate"
            value={safeFormData.bookingDate}
            onChange={onChange}
            min={today}
            required
          />
        </label>

        {/* ✅ START TIME */}
        <label>
          <span>Start Time</span>
          <input
            type="time"
            name="startTime"
            value={safeFormData.startTime}
            onChange={onChange}
            required
          />
        </label>

        {/* ✅ END TIME */}
        <label>
          <span>End Time</span>
          <input
            type="time"
            name="endTime"
            value={safeFormData.endTime}
            onChange={onChange}
            required
          />
        </label>

        {/* ✅ PURPOSE */}
        <label className="full-width">
          <span>Purpose</span>
          <textarea
            name="purpose"
            value={safeFormData.purpose}
            onChange={onChange}
            required
          />
        </label>

        {/* ✅ BUTTONS */}
        <div className="form-actions full-width">
          <button type="button" onClick={onAvailabilityCheck} disabled={loading}>
            Check Availability
          </button>

          <button type="submit" disabled={loading}>
            {loading ? "Creating..." : "Create Booking"}
          </button>
        </div>

        {/* ✅ ALERT */}
        {availabilityMsg && (
          <div className={`alert-box full-width ${availabilityMsg.type || ""}`}>
            {safe(availabilityMsg.message || availabilityMsg)}
          </div>
        )}
      </form>
    </div>
  );
};

export default memo(BookingForm);
